import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"\'()]+'
    urls = re.findall(url_pattern, myString)
    domains = set()
    for url in urls:
        try:
            parsed = urllib.parse.urlparse(url)
            domain = parsed.netloc
            if domain:
                domains.add(domain)
        except Exception:
            continue
    result = {}
    for domain in domains:
        try:
            response = requests.get(f'http://ip-api.com/json/{domain}?fields=status,country,region,city,isp,org,as,query&key={API_KEY}', timeout=10)
            if response.status_code == 200:
                data = response.json()
                result[domain] = data
            else:
                result[domain] = None
        except Exception:
            result[domain] = None
    return result

