import requests
import json
import pandas as pd
import seaborn as sns

HEADERS = {
    'accept': 'application/json'
}

def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")
    if parameters is None:
        raise Exception("Parameters must be provided.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to access URL: {e}")

    try:
        data = response.json()
    except json.JSONDecodeError as e:
        raise Exception(f"Invalid JSON data: {e}")

    if not data:
        raise Exception("Empty data received.")

    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Failed to convert data to DataFrame: {e}")

    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("No numerical columns found for correlation.")

    corr = numeric_df.corr()
    ax = sns.heatmap(corr, annot=True, cmap='coolwarm', square=True)
    ax.set_title('Correlation Heatmap')

    return (df, ax)
```

